+package main
+
+import (
+	"fmt"
+)
+
+// ScanArgError is a type of error that is expected to be returned
+// from the Scan() method of the Rows interface.
+type ScanArgError struct {
+	ColumnIndex int
+	Err         error
+}
+
+// Error implements the error interface.
+func (s ScanArgError) Error() string {
+	return fmt.Sprintf(
+		"error scanning input attribute with index %d: %s",
+		s.ColumnIndex, s.Err,
+	)
+}
+
+// ErrorWithStructNames provides a more detailed error message with struct and column names.
+func (s ScanArgError) ErrorWithStructNames(structName string, colName string) ScanArgError {
+	return ScanArgError{
+		ColumnIndex: s.ColumnIndex,
+		Err: fmt.Errorf("error scanning %s.%s: %w", structName, colName, s.Err),
+	}
+}
+
+func main() {
+	// Create a ScanArgError
+	err := ScanArgError{
+		ColumnIndex: 2,
+		Err:         fmt.Errorf("invalid syntax"),
+	}
+	
+	// Test the original Error method
+	fmt.Println("Original error:", err.Error())
+	
+	// Test the enhanced ErrorWithStructNames method
+	enhancedErr := err.ErrorWithStructNames("User", "Email")
+	fmt.Println("Enhanced error:", enhancedErr.Error())
+	
+	// Verify that the enhanced error is still a ScanArgError
+	if scanErr, ok := enhancedErr.(ScanArgError); ok {
+		fmt.Printf("Successfully preserved ScanArgError type with ColumnIndex: %d\n", scanErr.ColumnIndex)
+	} else {
+		fmt.Println("Failed to preserve ScanArgError type")
+	}
